import sys
import math

def is_zx_number(n):
    if n < 6:
        return 0

    for a in range(2, n // 3 + 2):
        for b in range(a, (n - a) // 2 + 1):
            c = n - a - b
            if c < b:
                continue
            g = math.gcd(math.gcd(a, b), c)
            if g == 1:
                return [a, b, c]

    return 0

def main():
    n = int(sys.stdin.readline().strip())
    result = is_zx_number(n)
    if result == 0:
        print(0)
    else:
        print(' '.join(map(str, result)))

if __name__ == "__main__":
    main()
